        let r = cp.firstChild; if (!r) { r = document.createElementNS(NS, 'rect'); cp.appendChild(r); }
        r.setAttribute('x', -200); r.setAttribute('width', 1360); r.setAttribute('y', q.clip[0].toFixed(2)); r.setAttribute('height', (q.clip[1] - q.clip[0]).toFixed(2));
